-- Indeling van de 294 woorden die de allergenenkeuring op 2026-10-26 nog niet kende.
--
-- Elk woord krijgt een eigen regel met een notitie, zodat in Beheer te zien is
-- waarom het zo is ingedeeld. Opnieuw uitvoeren is veilig: dezelfde woorden
-- worden bijgewerkt in plaats van dubbel toegevoegd.
--
--   bron         het woord is een bron van een allergeen uit onze lijst
--   onduidelijk  het woord kan een allergeen verbergen dat er niet bij staat
--   onschuldig   geen allergeen in onze lijst en verbergt er ook geen
--
-- De indeling volgt de bestaande woordenlijst: planten en vruchten krijgen de
-- soort-sleutel of anders de algemene sleutel (herbs, fruit, vegetables).
-- Dierlijke delen zonder genoemde soort worden "onduidelijk" met de vleeskeys.
-- Bereidings-, herkomst- en vulwoorden zijn onschuldig. Woorden die al goed
-- ingedeeld waren, staan hier niet in.
--
-- Verdeling: 109 bron, 47 onduidelijk, 138 onschuldig.

begin;

on conflict (term) do update set
  kind = excluded.kind,
  allergen_keys = excluded.allergen_keys,
  note = excluded.note;

-- Controle: hoeveel woorden staan er nu per soort?
select kind, count(*) as aantal from public.ingredient_terms group by kind order by kind;

-- Controle: de hele woordenlijst, zodat de nieuwe regels zichtbaar zijn.
select term, kind, allergen_keys, note from public.ingredient_terms order by term;

commit;
